import {createSudoku,sudokuConflicts,makeWordGraph,createLadder,shortestPath,oneLetter} from './puzzles.js';
import {ladderWords,commonLadderWords} from './ladder-words.js';
const fullGraph=makeWordGraph(ladderWords),commonGraph=makeWordGraph(commonLadderWords);
export function puzzleUI(api){const {$,main,toast,save,confirmAction}=api;const state=()=>api.state();
const seed=()=>{const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0];};
function current(type){const box=state().extras[type];if(!box.current){box.current=type==='sudoku'?createSudoku(seed()):createLadder(seed(),commonGraph);save();}return box.current;}
function record(type,g){const history=state().extras[type].history;if(g.complete&&!g.revealed&&!history.some(h=>h.id===g.id))history.push({id:g.id,date:api.today(),hints:g.hints});}
function newPuzzle(type,level){const g=current(type),run=()=>{state().extras[type].current=type==='sudoku'?createSudoku(seed(),level||g.level):createLadder(seed(),commonGraph);save();render(type);};const played=type==='sudoku'?g.board.some((n,i)=>n!==g.givens[i])||g.notes.some(n=>n.length):g.path.length>1;if(played&&!g.complete&&!g.revealed)confirmAction('Start another puzzle?','Your current unfinished '+(type==='sudoku'?'Sudoku':'word ladder')+' will be replaced. Completed results stay in Progress.',run);else run();}
function reveal(type){const g=current(type);if(g.complete||g.revealed)return;confirmAction('Show the answer?','This ends this puzzle and will not count as a win.',()=>{if(g.complete||g.revealed)return;g.revealed=true;save();render(type);});}
function render(type){if(type==='sudoku')renderSudoku();else renderLadder();}
function snapshot(g){g.undo.push({board:[...g.board],notes:g.notes.map(n=>[...n])});if(g.undo.length>30)g.undo.shift();}
function finishSudoku(g){g.complete=g.board.every((n,i)=>n===g.solution[i]);if(g.complete){g.undo=[];record('sudoku',g);toast('Sudoku complete. Beautifully solved.');}save();renderSudoku();}
function sudokuInput(value){const g=current('sudoku');if(g.complete||g.revealed)return;if(value==='undo'){const previous=g.undo.pop();if(previous){g.board=previous.board;g.notes=previous.notes;save();renderSudoku();}return;}if(value==='notes'){g.noteMode=!g.noteMode;save();renderSudoku();return;}if(value==='hint'&&(g.selected<0||g.givens[g.selected]||g.board[g.selected]===g.solution[g.selected]))g.selected=g.board.findIndex((n,i)=>n!==g.solution[i]);if(g.selected<0)return toast('Choose an empty cell first.');const i=g.selected;if(g.givens[i])return toast('That is a starting clue. Choose an empty cell.');
if(value==='hint'){if(g.board[i]===g.solution[i])return toast('This cell is already correct.');snapshot(g);g.board[i]=g.solution[i];g.notes[i]=[];g.hints++;finishSudoku(g);return;}const n=Number(value);if(!Number.isInteger(n)||n<0||n>9)return;snapshot(g);if(g.noteMode&&n){if(g.board[i]){g.undo.pop();return toast('Erase this value before adding notes.');}g.notes[i]=g.notes[i].includes(n)?g.notes[i].filter(v=>v!==n):[...g.notes[i],n].sort();}else{g.board[i]=n;g.notes[i]=[];}finishSudoku(g);}
function renderSudoku(){const g=current('sudoku'),displayBoard=g.revealed?g.solution:g.board,bad=sudokuConflicts(displayBoard),filled=displayBoard.filter(Boolean).length,finished=g.complete||g.revealed;main.innerHTML=`<section class="puzzle-layout"><div class="puzzle-intro"><div class="eyebrow">A moment of logic</div><h1>Make every<br>number count.</h1><p>Fill each row, column, and 3×3 box with the numbers 1–9, without repeating.</p><div class="puzzle-info"><span>✓ One verified solution</span><span>↺ Progress saved after every move</span></div><p class="note">Tap a cell, then a number. Pencil notes help you keep track of possibilities. Red outlines flag repeated numbers.</p><label class="level-label" for="level">Starting clues</label><select id="level"><option value="gentle" ${g.level==='gentle'?'selected':''}>More clues · gentle</option><option value="standard" ${g.level==='standard'?'selected':''}>Fewer clues · standard</option></select><button id="sudoku-new" class="text-button">New puzzle →</button></div><div class="sudoku-game"><div class="game-top"><span>Sudoku</span><span>${filled} / 81 filled</span></div><div class="sudoku-grid" role="grid" aria-label="Sudoku grid">${displayBoard.map((n,i)=>{const r=Math.floor(i/9),c=i%9,selected=g.selected===i,related=g.selected>=0&&(Math.floor(g.selected/9)===r||g.selected%9===c);return `<button role="gridcell" tabindex="${selected||g.selected===-1&&i===0?'0':'-1'}" data-cell="${i}" class="sudoku-cell ${g.givens[i]?'given':''} ${selected?'selected':related?'related':''} ${bad.has(i)?'conflict':''} ${c===2||c===5?'box-right':''} ${r===2||r===5?'box-bottom':''}" aria-selected="${selected}" aria-label="Row ${r+1}, column ${c+1}, ${n?n+(g.givens[i]?', starting clue':''):g.notes[i].length?'notes '+g.notes[i].join(', '):'empty'}${bad.has(i)?', conflicting value':''}">${n||`<span class="notes">${Array.from({length:9},(_,j)=>`<span>${g.notes[i].includes(j+1)?j+1:''}</span>`).join('')}</span>`}</button>`;}).join('')}</div><div class="message" role="status">${g.revealed?'Answer revealed · Not counted as a win':g.complete?'Puzzle complete ✓':bad.size?bad.size+' cells have a repeated number.':g.noteMode?'Pencil notes are on.':'Choose a cell, then enter a number.'}</div><div class="number-pad">${Array.from({length:9},(_,i)=>`<button class="key" data-number="${i+1}" ${finished?'disabled':''}>${i+1}</button>`).join('')}</div><div class="actions sudoku-tools"><button class="secondary ${g.noteMode?'active':''}" data-sudoku="notes" aria-pressed="${g.noteMode}" ${finished?'disabled':''}>✎ Notes</button><button class="secondary" data-sudoku="0" ${finished?'disabled':''}>Erase</button><button class="secondary" data-sudoku="undo" ${finished||!g.undo.length?'disabled':''}>Undo</button><button class="secondary" data-sudoku="hint" ${finished?'disabled':''}>Hint</button><button class="secondary" id="sudoku-answer" ${finished?'disabled':''}>Show answer</button></div>${finished?'<div class="result"><h2>'+(g.revealed?'Answer revealed':'Every piece in place.')+'</h2><p>'+(g.revealed?'Solution shown above · Not counted as a win':g.hints+' hints used · Saved to your progress')+'</p><button class="primary" id="sudoku-next">Next puzzle →</button></div>':'<p class="note">Hints used: '+g.hints+' · Keyboard: 1–9, arrows, Backspace</p>'}</div></section>`;
main.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{g.selected=Number(b.dataset.cell);save();renderSudoku();main.querySelector(`[data-cell="${g.selected}"]`).focus({preventScroll:true});});main.querySelectorAll('[data-number]').forEach(b=>b.onclick=()=>sudokuInput(b.dataset.number));main.querySelectorAll('[data-sudoku]').forEach(b=>b.onclick=()=>sudokuInput(b.dataset.sudoku));$('#sudoku-answer').onclick=()=>reveal('sudoku');$('#sudoku-new').onclick=()=>newPuzzle('sudoku');$('#level').onchange=e=>{const next=e.target.value;e.target.value=g.level;newPuzzle('sudoku',next);};if($('#sudoku-next'))$('#sudoku-next').onclick=()=>newPuzzle('sudoku');}
function addLadder(){const g=current('ladder'),input=$('#ladder-input'),word=input.value.trim().toLowerCase();if(g.complete||g.revealed)return;if(word.length!==4||!/^[a-z]+$/.test(word))return toast('Enter a four-letter word.');if(!fullGraph.words.has(word))return toast('That word is not in the dictionary.');if(!oneLetter(g.path.at(-1),word))return toast('Change exactly one letter. Keep the other letters in place.');if(g.path.includes(word))return toast('You have used that word. Undo to backtrack.');g.path.push(word);g.draft='';g.complete=word===g.target;record('ladder',g);save();renderLadder();if(!g.complete)$('#ladder-input').focus({preventScroll:true});else toast('You reached '+g.target.toUpperCase()+'. Nicely connected.');}
function renderLadder(){const g=current('ladder'),finished=g.complete||g.revealed,answerPath=g.revealed?(shortestPath(commonGraph,g.start,g.target)||shortestPath(fullGraph,g.start,g.target)):null;main.innerHTML=`<section class="puzzle-layout"><div class="puzzle-intro"><div class="eyebrow">One small change</div><h1>Find a way<br>with words.</h1><p>Turn <strong>${g.start.toUpperCase()}</strong> into <strong>${g.target.toUpperCase()}</strong>, changing just one letter at each step.</p><div class="puzzle-info"><span>Every step must be a real word.</span><span>Keep all four letters in their positions.</span></div><p class="note">A common-word route takes ${g.par} steps. Explore your own route, or undo a step to try another direction.</p><button class="text-button" id="ladder-new">New ladder →</button></div><div class="ladder-game"><div class="ladder-endpoints"><div><span class="eyebrow">From</span><strong>${g.start.toUpperCase()}</strong></div><span class="endpoint-arrow">→</span><div><span class="eyebrow">To</span><strong>${g.target.toUpperCase()}</strong></div></div><div class="ladder-path" aria-label="Your word ladder">${g.path.map((w,i)=>`<div class="ladder-step"><span class="step-number">${i}</span><div>${[...w].map((c,j)=>`<span class="letter ${i&&g.path[i-1][j]!==c?'changed':''}">${c.toUpperCase()}</span>`).join('')}</div>${i===g.path.length-1?'<span class="path-marker">'+(g.complete?'✓':'←')+'</span>':''}</div>`).join('')}</div>${finished?`<div class="result"><h2>${g.revealed?'Answer revealed':'Connected.'}</h2>${g.revealed?`<p>One route from the start:</p><p class="answer-route">${answerPath?.map(w=>w.toUpperCase()).join(' → ')||'No route found.'}</p><p>Not counted as a win.</p>`:`<p>${g.path.length-1} steps · ${g.hints} hints used</p>`}<button class="primary" id="ladder-next">Next ladder →</button></div>`:`<form id="ladder-form"><label for="ladder-input">Your next word</label><div class="ladder-entry"><input id="ladder-input" type="text" maxlength="4" minlength="4" pattern="[A-Za-z]{4}" autocomplete="off" autocorrect="off" autocapitalize="characters" spellcheck="false" aria-describedby="ladder-prompt"><button class="primary" type="submit">Add ↑</button></div><p id="ladder-prompt" class="note">Change one letter in ${g.path.at(-1).toUpperCase()}.</p></form><div class="actions"><button class="secondary" id="ladder-undo" ${g.path.length<2?'disabled':''}>Undo step</button><button class="secondary" id="ladder-hint">Hint</button><button class="secondary" id="ladder-answer">Show answer</button></div><p class="note">${g.path.length-1} steps taken · ${g.hints} hints used</p>`}</div></section>`;
$('#ladder-new').onclick=()=>newPuzzle('ladder');if(finished){$('#ladder-next').onclick=()=>newPuzzle('ladder');return;}$('#ladder-answer').onclick=()=>reveal('ladder');$('#ladder-input').value=g.draft||'';$('#ladder-input').oninput=e=>{g.draft=e.target.value.replace(/[^a-z]/gi,'').toLowerCase().slice(0,4);e.target.value=g.draft.toUpperCase();save();};$('#ladder-form').onsubmit=e=>{e.preventDefault();addLadder();};$('#ladder-undo').onclick=()=>{if(g.path.length>1){g.path.pop();g.draft='';save();renderLadder();}};$('#ladder-hint').onclick=()=>{const currentWord=g.path.at(-1),path=shortestPath(commonGraph,currentWord,g.target)||shortestPath(fullGraph,currentWord,g.target);if(path?.length>1){g.hints++;save();api.showDialog('One possible next step',`<p>Try <strong>${path[1].toUpperCase()}</strong>.</p><p>Change one letter in ${currentWord.toUpperCase()}. ${path.length-1} steps remain along this route. If the hint returns to an earlier word, use Undo to backtrack there.</p>`);}else toast('Try undoing a step to explore another route.');};}
function key(e){if(api.view()!=='sudoku'||e.target.closest('input,select,textarea,dialog'))return;const g=current('sudoku');if(/^Arrow/.test(e.key)){e.preventDefault();const i=Math.max(g.selected,0),delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-9,ArrowDown:9}[e.key];if(delta!==undefined){g.selected=Math.min(80,Math.max(0,i+delta));save();renderSudoku();main.querySelector(`[data-cell="${g.selected}"]`).focus({preventScroll:true});}}else if(/^[1-9]$/.test(e.key)){e.preventDefault();sudokuInput(e.key);}else if(['Backspace','Delete','0'].includes(e.key)){e.preventDefault();sudokuInput('0');}}
return {render,key};}
